import logging
import time
from contextlib import contextmanager
from functools import cached_property
from threading import Lock
from typing import Optional

import attr
from taf.config.testline.pdu import Pdu  # type: ignore
from taf.hw.pdu import BadResponse, pdu  # type: ignore


class SinglePduLock:
    _instances: dict[type, "SinglePduLock"] = {}

    def __new__(cls, *args, **kwargs):
        if cls not in cls._instances:
            cls._instances[cls] = super().__new__(cls, *args, **kwargs)
        return cls._instances[cls]

    def __init__(self):
        self.lock = Lock()


@attr.s(cmp=False, hash=True)
class TAFPDU:
    port = attr.ib(type=int)
    pdu_data = attr.ib(type=Pdu, default=None, hash=False)
    device_name = attr.ib(type=str, default="")
    address = attr.ib(type=str, default="")
    protocol = attr.ib(type=Optional[str], default=None)
    lock = attr.ib(default=SinglePduLock().lock, type=Lock, init=False, repr=False, hash=False)

    def __attrs_post_init__(self):
        if self.pdu_data:
            self.address = self.pdu_data.addr
            self.device_name = self.pdu_data.vendor or type(self.pdu_data).__name__
            self.protocol = getattr(self.pdu_data, "protocol", None)
        if self.device_name.upper() == "PKC16":
            self.device_name = "PKC"
        elif self.device_name.upper() == "ATEN24":
            self.device_name = "ATEN"

    @cached_property
    def pdu_instance(self) -> pdu:
        return pdu()

    def get_pdu_status(self, alias: str, logger: logging.Logger) -> str:
        for attempt in range(5):
            with pdu_access(self, alias, logger) as new_pdu_access:
                try:
                    return new_pdu_access.get_port_status(self.port, pdu_device=alias).lower()
                except BadResponse as err:
                    logger.debug(err)
                    time.sleep(10 * (attempt + 1))
        raise BadResponse(f"Could not get status for PDU {self.address} port {self.port}")

    def reset_port_with_verification(self, alias: str, logger: logging.Logger) -> None:
        with pdu_access(self, alias, logger) as new_pdu_access:
            self._change_port_status("off", new_pdu_access, alias, logger)
            time.sleep(5)
            self._change_port_status("on", new_pdu_access, alias, logger)

    def _change_port_status(self, status: str, new_pdu_access: pdu, alias: str, logger: logging.Logger) -> None:
        power_method = new_pdu_access.power_off if status == "off" else new_pdu_access.power_on
        for _ in range(3):
            try:
                power_method(self.port, pdu_device=alias)
                if self._verify_pdu_state(new_pdu_access, alias, status, 10, logger):
                    return
            except Exception as err:
                logger.warning(f"Failed to change PDU port {self.port} status to {status}: {err}")
                time.sleep(3)
        raise PduPortNotChanged(self, status)

    def _verify_pdu_state(self, new_pdu_access: pdu, alias: str, status: str, timeout: int, logger: logging.Logger) -> bool:
        start_time = time.time()
        while time.time() - start_time < timeout:
            outlet_status = new_pdu_access.get_port_status(self.port, pdu_device=alias).lower()
            try:
                assert outlet_status == status
                logger.debug(f"Socket {self.port} status is as expected = {outlet_status}")
                return True
            except AssertionError:
                logger.debug(f"Socket {self.port} status = {outlet_status}")
                time.sleep(1)
        else:
            return False

    def teardown_pdu(self, alias: str) -> None:
        try:
            self.pdu_instance.teardown_pdu(pdu_device=alias)
        except NotImplementedError:
            pass

    def setup_pdu(self, alias: str) -> None:
        if self.pdu_data:
            self.pdu_instance.setup_pdu(self.pdu_data, alias=alias)
        elif self.protocol:
            self.pdu_instance.setup_pdu(
                model=self.device_name,
                alias=alias,
                host=self.address,
                protocol=self.protocol,
            )
        else:
            self.pdu_instance.setup_pdu(
                model=self.device_name,
                alias=alias,
                host=self.address,
            )


class PduPortNotChanged(Exception):
    def __init__(self, pdu: TAFPDU, status: str) -> None:
        super().__init__()
        self.pdu = pdu
        self.target_status = status
        self.initial_status = "on" if status == "off" else "off"

    def __str__(self):
        return "Pdu {} port {} status ({}->{}) did not change in time.".format(
            self.pdu.address, self.pdu.port, self.initial_status, self.target_status
        )


@contextmanager
def pdu_access(pdu: TAFPDU, alias: str, logger: logging.Logger) -> pdu:
    with pdu.lock:
        try:
            logger.debug(f"SETUP START: PDU: [{pdu.address}, {pdu.device_name}, {pdu.protocol}, {alias}]")
            pdu.setup_pdu(alias)
            logger.debug(f"SETUP DONE: PDU: [{pdu.address}, {pdu.device_name}, {pdu.protocol}, {alias}]")
            yield pdu.pdu_instance
        finally:
            try:
                logger.debug(f"TEARDOWN START: PDU: [{pdu.address}, {pdu.device_name}, {pdu.protocol}, {alias}]")
                pdu.teardown_pdu(alias)
                logger.debug(f"TEARDOWN DONE: PDU: [{pdu.address}, {pdu.device_name}, {pdu.protocol}, {alias}]")
            except Exception as exc:
                logger.warning(exc, exc_info=True)
